entries[1226159] = { ["name"] = "Amani Angler's Ward", ["text"] = "2 sec cast\nReagents:\nBlood Hunter (2)\nA powerful totem that prevents the spirit of Blood Hunters from taking revenge on Anglers who reel it in.\nProfession:\nFishing\n\nAmani Angler's Ward\n\nUse: Wards any Blood Hunter from attacking for 30 min.\n80" }
