entries[1226166] = { ["name"] = "Farstrider Rations", ["text"] = "2 sec cast\nReagents:\nPractically Pork (2), Pouch of Spices , Thalassian Herbs\nOptional Reagents:\nSecret Ingredient (#480)\nRecipe for 4 servings. Actual number of servings will vary based on cooking skill.\nProfession Trainer:\nMidnight Cooking (25)\nCost:\n120\n\nUse: Restores 5% of your maximum health every second over 20 sec. Must remain seated while eating.\n\nWell Fed\nIf you spend at least 10 seconds eating, you will become Well Fed and gain ( 32 * .5) Mastery and ( 32 * .5) Haste for 1 hour.\n80" }
entries[1226167] = { ["name"] = "Hearty Food", ["text"] = "2 sec cast\nCondense 5 of your favorite meal to create a version that is sure to keep you satiated!\n\nHearty food persists through death and is able to be shared amongst your Warband.\nProfession:\nCooking (35)" }
